            case SUCCESS, FAILED -> { ... existing ... }
            case CANCEL_REQUESTED -> throw ApiException.conflict("TASK_CANCEL_REQUESTED", "任务取消待确认，只接受停止确认");
            case CANCELLED -> throw ApiException.conflict("TASK_CANCELLED", "任务已取消，回执不再受理");
