      v1 = release 1.0.0->2.0.0 100
      t1 = installTask(v1, d1)
      releaseService.cancel(v1)
      v2 = release 1.0.0->3.0.0
      t2 = installTask(v2, d1)
      concurrent: start(t1), start(t2) -> one INSTALLING one 422 SLOT_OCCUPIED
      assert count device_slot='d1' == 1

